  // ── إكمال الجمل (مبتدئ) ─────────────────────────────────
  Question(id: 'q201', text: 'أكمل الجملة بالكلمة المناسبة:\n"ذهب الطالب إلى المكتبة لأنه أراد أن ______ كتاباً جديداً."', options: ['يستعير', 'يبيع', 'يكسر', 'يهمل'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'المكتبة مكان استعارة الكتب، فـ"يستعير" هي الكلمة المناسبة لسياق الجملة.'),
  Question(id: 'q202', text: 'أكمل الجملة بالكلمة المناسبة:\n"يحتاج النبات إلى الماء وضوء الشمس حتى ______."', options: ['ينمو', 'يذبل', 'يجف', 'يحترق'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'الماء والشمس عوامل تساعد النبات على النمو، فـ"ينمو" هي المناسبة.'),
  Question(id: 'q203', text: 'أكمل الجملة بالكلمة المناسبة:\n"اجتهد الطالب في مذاكرته فحصل على ______ ممتازة."', options: ['درجة', 'عقوبة', 'غياب', 'إجازة'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'نتيجة الاجتهاد الطبيعية هي الحصول على درجة ممتازة.'),
  Question(id: 'q204', text: 'أكمل الجملة بالكلمة المناسبة:\n"شعرت بالعطش الشديد بعد الجري، فشربت كوباً كبيراً من ______."', options: ['الماء', 'الزيت', 'الرمل', 'الدخان'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'الماء هو ما يروي العطش، فهو المناسب لسياق الجملة.'),
  Question(id: 'q205', text: 'أكمل الجملة بالكلمة المناسبة:\n"أطفأ رجال الإطفاء النار بسرعة قبل أن ______ إلى المنازل المجاورة."', options: ['تنتشر', 'تنطفئ', 'تبرد', 'تهدأ'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'المعنى المقصود أن النار قد تمتد لأماكن أخرى، وهذا معنى "تنتشر".'),
  Question(id: 'q206', text: 'أكمل الجملة بالكلمة المناسبة:\n"كان الجو بارداً جداً، فارتدى الولد ملابس ______."', options: ['ثقيلة', 'خفيفة', 'ممزقة', 'صيفية'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'في الطقس البارد تُرتدى الملابس الثقيلة (الشتوية) للدفء.'),
  Question(id: 'q207', text: 'أكمل الجملة بالكلمة المناسبة:\n"عندما رنّ جرس المدرسة، ______ الطلاب إلى فصولهم."', options: ['توجه', 'هرب', 'ابتعد', 'نام'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'رنين الجرس إشارة لبدء الحصة، فيتوجه الطلاب لفصولهم.'),
  Question(id: 'q208', text: 'أكمل الجملة بالكلمة المناسبة:\n"لم يستطع المريض النوم بسبب ______ الشديد في رأسه."', options: ['الألم', 'النشاط', 'الفرح', 'الجوع'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'الألم هو السبب المنطقي الذي يمنع المريض من النوم.'),
  Question(id: 'q209', text: 'أكمل الجملة بالكلمة المناسبة:\n"سقطت الأمطار بغزارة، فامتلأت الشوارع بـ______."', options: ['المياه', 'الرمال', 'الأوراق', 'الغبار'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'نتيجة سقوط الأمطار الغزيرة المنطقية هي امتلاء الشوارع بالمياه.'),
  Question(id: 'q210', text: 'أكمل الجملة بالكلمة المناسبة:\n"كافأت المعلمة الطالب المجتهد بشهادة ______."', options: ['تقدير', 'إنذار', 'غياب', 'توبيخ'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'المكافأة على الاجتهاد تكون بشهادة تقدير، وهي كلمة إيجابية تناسب السياق.'),
  Question(id: 'q211', text: 'أكمل الجملة بالكلمة المناسبة:\n"وضع الطباخ الطعام في الفرن حتى ______."', options: ['ينضج', 'يبرد', 'يفسد', 'يتجمد'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'الغاية من وضع الطعام في الفرن هي أن ينضج.'),
  Question(id: 'q212', text: 'أكمل الجملة بالكلمة المناسبة:\n"أغلق الطالب النافذة لأن الرياح كانت ______."', options: ['قوية', 'هادئة', 'دافئة', 'معطرة'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'إغلاق النافذة يكون بسبب رياح قوية مزعجة.'),
  Question(id: 'q213', text: 'أكمل الجملة بالكلمة المناسبة:\n"لم يجد المفتاح رغم ______ الطويل في البحث عنه."', options: ['الجهد', 'النوم', 'اللعب', 'الفرح'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'البحث عن شيء مفقود يستلزم بذل الجهد.'),
  Question(id: 'q214', text: 'أكمل الجملة بالكلمة المناسبة:\n"يرتدي الطبيب المئزر الأبيض قبل أن يبدأ ______ المرضى."', options: ['فحص', 'إهمال', 'تجاهل', 'مغادرة'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'دور الطبيب الأساسي هو فحص المرضى.'),
  Question(id: 'q215', text: 'أكمل الجملة بالكلمة المناسبة:\n"تأخر القطار عن موعده، فانتظره المسافرون بـ______."', options: ['قلق', 'فرح', 'راحة', 'نشاط'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'تأخر القطار يسبب القلق للمسافرين المنتظرين.'),
  Question(id: 'q216', text: 'أكمل الجملة بالكلمة المناسبة:\n"سقى الفلاح أشجاره كل صباح حتى ______ ثمارها."', options: ['تنضج', 'تذبل', 'تسقط', 'تتعفن'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'غاية الفلاح من السقي المنتظم هي نضج الثمار.'),
  Question(id: 'q217', text: 'أكمل الجملة بالكلمة المناسبة:\n"عمّت الفوضى الملعب بعد أن ______ الفريق الهدف الفائز."', options: ['سجّل', 'خسر', 'أضاع', 'ترك'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'تسجيل الهدف الفائز هو ما يثير فرح الجمهور وفوضى الاحتفال.'),

  // ── إكمال الجمل (متوسط) ─────────────────────────────────
  Question(id: 'q218', text: 'أكمل الجملة بالكلمة المناسبة:\n"رغم الصعوبات التي واجهها، ظل ______ على تحقيق هدفه."', options: ['مصرّاً', 'متردداً', 'يائساً', 'غافلاً'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: '"رغم الصعوبات" و"ظل" تدلان على استمرار العزيمة، وهذا معنى "مصرّاً".'),
  Question(id: 'q219', text: 'أكمل الجملة بالكلمة المناسبة:\n"اتخذ المدير قراره بعد ______ طويل في جميع الجوانب."', options: ['تفكير', 'تسرع', 'إهمال', 'نسيان'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'القرار المدروس يأتي بعد تفكير طويل، لا تسرع أو إهمال.'),
  Question(id: 'q220', text: 'أكمل الجملة بالكلمة المناسبة:\n"لم تتضح الرؤية أمام السائقين بسبب ______ الكثيف الذي غطى الطريق."', options: ['الضباب', 'ضوء الشمس', 'الهدوء', 'النظام'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'الضباب الكثيف هو ما يحجب الرؤية عن السائقين.'),
  Question(id: 'q221', text: 'أكمل الجملة بالكلمة المناسبة:\n"حاول المفاوضون التوصل إلى حل ______ يرضي الطرفين."', options: ['وسط', 'متطرف', 'مؤجل', 'منفرد'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'إرضاء الطرفين يستلزم حلاً وسطاً بينهما.'),
  Question(id: 'q222', text: 'أكمل الجملة بالكلمة المناسبة:\n"أدى الإهمال المستمر في الصيانة إلى ______ الجسر بعد سنوات قليلة."', options: ['تصدع', 'تجديد', 'تحصين', 'تزيين'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'الإهمال في الصيانة يؤدي إلى الضرر (تصدع)، لا التحسن.'),
  Question(id: 'q223', text: 'أكمل الجملة بالكلمة المناسبة:\n"يتميز هذا العالِم بقدرته على ______ الأفكار المعقدة بأسلوب بسيط."', options: ['تبسيط', 'تعقيد', 'إخفاء', 'تجاهل'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'الجملة تنص على "أسلوب بسيط"، وهذا يتفق مع معنى "تبسيط".'),
  Question(id: 'q224', text: 'أكمل الجملة بالكلمة المناسبة:\n"وقف الخطيب أمام الجمهور بثقة و______ في الحديث."', options: ['طلاقة', 'تلعثم', 'صمت', 'خجل'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: '"بثقة" تتفق مع "طلاقة" في الحديث، لا التلعثم أو الخجل.'),
  Question(id: 'q225', text: 'أكمل الجملة بالكلمة المناسبة:\n"بذل الفريق جهداً ______ حتى تمكن من الفوز باللقب."', options: ['مضنياً', 'يسيراً', 'قليلاً', 'عابراً'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'الفوز باللقب عادة يستلزم جهداً كبيراً ومضنياً لا يسيراً.'),
  Question(id: 'q226', text: 'أكمل الجملة بالكلمة المناسبة:\n"انتشرت الشائعات بسرعة بسبب ______ الجمهور تجاه الحقيقة."', options: ['جهل', 'إدراك', 'معرفة', 'وعي'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'انتشار الشائعات غالباً ما يكون بسبب الجهل بالحقيقة، لا معرفتها.'),
  Question(id: 'q227', text: 'أكمل الجملة بالكلمة المناسبة:\n"تسعى الدول النامية إلى ______ اقتصادها لمواكبة التطور العالمي."', options: ['تنمية', 'تجميد', 'إهمال', 'تقييد'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'مواكبة التطور تستلزم تنمية الاقتصاد لا تجميده.'),
  Question(id: 'q228', text: 'أكمل الجملة بالكلمة المناسبة:\n"يتطلب اتخاذ القرارات المصيرية ______ العواقب قبل الإقدام عليها."', options: ['تقدير', 'تجاهل', 'نسيان', 'إغفال'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'القرار الحكيم يستلزم تقدير العواقب لا تجاهلها.'),
  Question(id: 'q229', text: 'أكمل الجملة بالكلمة المناسبة:\n"عاش الكاتب في ______ عن الناس ليتفرغ لتأليف كتبه."', options: ['عزلة', 'مخالطة', 'صخب', 'ازدحام'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'التفرغ للتأليف غالباً يستلزم الابتعاد عن الناس، وهذا معنى العزلة.'),
  Question(id: 'q230', text: 'أكمل الجملة بالكلمة المناسبة:\n"تعامل الحكم مع الحادثة بـ______ تام رغم ضغط الجمهور."', options: ['حياد', 'انحياز', 'تحيّز', 'ميل'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'مقاومة ضغط الجمهور تعني الالتزام بالحياد، لا الانحياز.'),
  Question(id: 'q231', text: 'أكمل الجملة بالكلمة المناسبة:\n"واجه المستكشف مخاطر عديدة، لكنه لم يفقد ______ في إتمام رحلته."', options: ['عزيمته', 'خوفه', 'ترددّه', 'يأسه'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: '"لكنه لم يفقد" تدل على استمرار أمر إيجابي رغم المخاطر، وهذا معنى العزيمة.'),
  Question(id: 'q232', text: 'أكمل الجملة بالكلمة المناسبة:\n"أدت زيادة الطلب على السلعة إلى ______ في سعرها."', options: ['ارتفاع', 'انخفاض', 'ثبات', 'اختفاء'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'زيادة الطلب اقتصادياً تؤدي إلى ارتفاع السعر.'),
  Question(id: 'q233', text: 'أكمل الجملة بالكلمة المناسبة:\n"أبدى الطبيب ______ كبيراً في متابعة حالة المريض يومياً."', options: ['اهتماماً', 'إهمالاً', 'تجاهلاً', 'ملالاً'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'المتابعة اليومية للمريض تدل على الاهتمام لا الإهمال.'),
  Question(id: 'q234', text: 'أكمل الجملة بالكلمة المناسبة:\n"يعتمد نجاح المشروع على ______ دقيق للموارد المتاحة."', options: ['تخطيط', 'إهدار', 'تبديد', 'إسراف'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'النجاح يستلزم تخطيطاً دقيقاً لا إهداراً أو تبديداً للموارد.'),

  // ── إكمال الجمل (صعب) ───────────────────────────────────
  Question(id: 'q235', text: 'أكمل الجملة بالكلمة المناسبة:\n"يتّسم أسلوب الكاتب بـ______ الألفاظ ووضوح المعاني رغم عمق أفكاره."', options: ['سلاسة', 'ركاكة', 'استغلاق', 'تعقيد'], correctIndex: 0, difficulty: Difficulty.hard, explanation: '"وضوح المعاني" يتناسق مع "سلاسة الألفاظ"، لا مع الركاكة أو التعقيد.'),
  Question(id: 'q236', text: 'أكمل الجملة بالكلمة المناسبة:\n"لم يتزعزع إيمان العالِم بنظريته رغم ______ زملائه المتكرر لها."', options: ['تفنيد', 'تأييد', 'تعزيز', 'دعم'], correctIndex: 0, difficulty: Difficulty.hard, explanation: '"لم يتزعزع رغم" تدل على مواجهة معارضة، وهذا معنى "تفنيد" (إبطال).'),
  Question(id: 'q237', text: 'أكمل الجملة بالكلمة المناسبة:\n"عُرف ذلك القائد بحنكته السياسية وقدرته على ______ الأزمات باقتدار."', options: ['احتواء', 'تأجيج', 'إشعال', 'تعميق'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'الحنكة السياسية تعني القدرة على احتواء الأزمات لا تأجيجها.'),
  Question(id: 'q238', text: 'أكمل الجملة بالكلمة المناسبة:\n"يسعى المصلحون إلى ______ الوعي المجتمعي بمخاطر الفساد الإداري."', options: ['ترسيخ', 'طمس', 'إخماد', 'تبديد'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'المصلح يهدف إلى تثبيت الوعي وتقويته، وهذا معنى "ترسيخ".'),
  Question(id: 'q239', text: 'أكمل الجملة بالكلمة المناسبة:\n"اتسمت مواقفه السياسية بالثبات وعدم ______ للضغوط الخارجية."', options: ['الانصياع', 'المقاومة', 'التصدي', 'الممانعة'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'الثبات يعني عدم الاستسلام للضغوط، وهذا معنى "الانصياع".'),
  Question(id: 'q240', text: 'أكمل الجملة بالكلمة المناسبة:\n"حاول الخطيب أن ______ الجمهور بحجج منطقية بدلاً من الخطابة العاطفية."', options: ['يقنع', 'يستفز', 'يثير', 'يستهزئ بـ'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'الحجج المنطقية وسيلة للإقناع لا للاستفزاز.'),
  Question(id: 'q241', text: 'أكمل الجملة بالكلمة المناسبة:\n"يعاني الاقتصاد من ______ حاد نتيجة تراجع الصادرات وارتفاع الديون."', options: ['ركود', 'ازدهار', 'انتعاش', 'نمو'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'تراجع الصادرات وارتفاع الديون مؤشرات سلبية تتفق مع "ركود" لا "ازدهار".'),
  Question(id: 'q242', text: 'أكمل الجملة بالكلمة المناسبة:\n"لم يتوانَ المحامي عن ______ حقوق موكله أمام القضاء رغم ضعف الأدلة."', options: ['الدفاع عن', 'التنازل عن', 'إهمال', 'التفريط في'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'دور المحامي الأساسي الدفاع عن موكله، ويؤكده "لم يتوانَ".'),
  Question(id: 'q243', text: 'أكمل الجملة بالكلمة المناسبة:\n"تعتمد الدبلوماسية الناجحة على ______ المصالح المشتركة بين الأطراف المتنازعة."', options: ['إيجاد', 'إلغاء', 'تجاهل', 'إخفاء'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'الدبلوماسية الناجحة تسعى لإيجاد أرضية مشتركة، لا إلغاءها.'),
  Question(id: 'q244', text: 'أكمل الجملة بالكلمة المناسبة:\n"رغم مكانته الرفيعة، ظل الوزير ______ في تعامله مع عامة الناس."', options: ['متواضعاً', 'متعالياً', 'متكبراً', 'مترفعاً'], correctIndex: 0, difficulty: Difficulty.hard, explanation: '"رغم مكانته الرفيعة" تفيد التناقض المتوقع، فالمعنى المناسب هو "متواضعاً".'),
  Question(id: 'q245', text: 'أكمل الجملة بالكلمة المناسبة:\n"تحتاج عملية الإصلاح الشامل إلى ______ حقيقية لا مجرد شعارات."', options: ['إرادة', 'رغبة عابرة', 'أمنية', 'محاولة سطحية'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'مقابل "مجرد شعارات" تحتاج الجملة لمعنى الجدية والصلابة، وهذا معنى "إرادة حقيقية".'),
  Question(id: 'q246', text: 'أكمل الجملة بالكلمة المناسبة:\n"يتصف الباحث الجاد بـ______ في التحقق من مصادره قبل النشر."', options: ['الدقة', 'التسرع', 'الإهمال', 'اللامبالاة'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'التحقق من المصادر قبل النشر يستلزم الدقة لا التسرع.'),

  // ── الخطأ السياقي (مبتدئ) ───────────────────────────────
  Question(id: 'q247', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"أقبل الطلاب على الدراسة بجدّ ونشاط وحماسة وكسل استعداداً للامتحانات."', options: ['جدّ', 'نشاط', 'حماسة', 'كسل'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'الكلمات الثلاث الأولى تصف حماس الطلاب واجتهادهم، وكسل تناقض هذا المعنى.'),
  Question(id: 'q248', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"احتفل الأطفال بيوم العيد فرحين مسرورين ضاحكين حزينين."', options: ['فرحين', 'مسرورين', 'ضاحكين', 'حزينين'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'أجواء العيد تدل على السرور، وحزينين تكسر هذا السياق الإيجابي.'),
  Question(id: 'q249', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"سقطت الأمطار الغزيرة فامتلأت الأنهار وارتوت الأرض وازدهرت المزروعات وجفّت البحيرات."', options: ['امتلأت الأنهار', 'ارتوت الأرض', 'ازدهرت المزروعات', 'جفّت البحيرات'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'الأمطار الغزيرة تؤدي لامتلاء المسطحات المائية، وجفاف البحيرات يناقض ذلك.'),
  Question(id: 'q250', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"وقف اللاعبون في الملعب مستعدين للمباراة، أقوياء نشيطين متحمسين متعبين."', options: ['أقوياء', 'نشيطين', 'متحمسين', 'متعبين'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'الاستعداد للمباراة يستلزم القوة والنشاط، ومتعبين يتناقض مع هذا الاستعداد.'),
  Question(id: 'q251', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"نظّف العمال الشوارع فأصبحت نقية طاهرة لامعة قذرة."', options: ['نقية', 'طاهرة', 'لامعة', 'قذرة'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'نتيجة التنظيف تكون النظافة، وقذرة تناقض هذا المعنى تماماً.'),
  Question(id: 'q252', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"أضاء القمر السماء ليلاً بنور هادئ ساطع جميل صاخب."', options: ['هادئ', 'ساطع', 'جميل', 'صاخب'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'الضوء يوصف بالهدوء والسطوع والجمال، أما "صاخب" فهي صفة صوتية لا تناسب وصف الضوء.'),
  Question(id: 'q253', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"عمل الفلاح في أرضه بجدّ وصبر وأناة وتهور حتى أتمّ الحصاد."', options: ['جدّ', 'صبر', 'أناة', 'تهور'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'الصبر والأناة يتناقضان مع التهور، فالفلاح المتأني لا يوصف بالتهور.'),
  Question(id: 'q254', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"اشتد البرد في الشتاء فارتدى الناس معاطف سميكة وقفازات وأوشحة وملابس خفيفة."', options: ['معاطف سميكة', 'قفازات', 'أوشحة', 'ملابس خفيفة'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'شدة البرد تستلزم الملابس الثقيلة الدافئة، لا الخفيفة.'),
  Question(id: 'q255', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"استمع الجمهور إلى الخطيب بانتباه وصمت وتركيز وضجيج."', options: ['انتباه', 'صمت', 'تركيز', 'ضجيج'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'الاستماع بانتباه وتركيز يستلزم الصمت لا الضجيج.'),
  Question(id: 'q256', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"طار العصفور في السماء بخفة ورشاقة وحرية وثقل."', options: ['خفة', 'رشاقة', 'حرية', 'ثقل'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'الطيران يوصف بالخفة، وثقل يتناقض مع هذا الوصف.'),
  Question(id: 'q257', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"نجح الطالب في اختباره لأنه ذاكر دروسه بانتظام وحل التمارين وراجع ملاحظاته وأهمل واجباته."', options: ['ذاكر دروسه بانتظام', 'حل التمارين', 'راجع ملاحظاته', 'أهمل واجباته'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'أسباب النجاح المذكورة كلها إيجابية، وإهمال الواجبات يتناقض معها.'),

  // ── الخطأ السياقي (متوسط) ───────────────────────────────
  Question(id: 'q258', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"تميز الموظف بالإخلاص في عمله والالتزام بمواعيده والدقة في أدائه والتهاون في مسؤولياته."', options: ['الإخلاص', 'الالتزام', 'الدقة', 'التهاون'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'الصفات الثلاث الأولى إيجابية تصف موظفاً مثالياً، والتهاون يناقضها.'),
  Question(id: 'q259', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"واجه الفريق الأزمة بثبات وحكمة وتعاون وارتباك."', options: ['ثبات', 'حكمة', 'تعاون', 'ارتباك'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'مواجهة الأزمة بنجاح تستلزم الثبات والحكمة، والارتباك يعاكس هذا المعنى.'),
  Question(id: 'q260', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"عالج الطبيب المريض بمهارة ودقة وسرعة وإهمال حتى تعافى تماماً."', options: ['مهارة', 'دقة', 'سرعة', 'إهمال'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'تعافي المريض التام يدل على علاج ناجح، والإهمال يناقض هذه النتيجة.'),
  Question(id: 'q261', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"اشتهرت تلك الحضارة بازدهار العلوم وتقدم الفنون ورقي العمارة وانتشار الأمية."', options: ['ازدهار العلوم', 'تقدم الفنون', 'رقي العمارة', 'انتشار الأمية'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'ازدهار العلوم والفنون يستلزم انتشار المعرفة لا الأمية.'),
  Question(id: 'q262', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"دافع المحامي عن موكله بحجج قوية وأدلة دامغة وثقة تامة وتردد واضح."', options: ['حجج قوية', 'أدلة دامغة', 'ثقة تامة', 'تردد واضح'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'القوة والثقة في الدفاع تتناقض مع التردد.'),
  Question(id: 'q263', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"أدار المدير الاجتماع بحزم ونظام ووضوح وفوضى."', options: ['حزم', 'نظام', 'وضوح', 'فوضى'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'الحزم والنظام يعنيان ضبط الاجتماع، والفوضى تناقض ذلك.'),
  Question(id: 'q264', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"انتشر الوعي البيئي بين الناس فقلّلوا من استهلاك البلاستيك وأعادوا تدوير النفايات وزرعوا الأشجار ولوّثوا الأنهار."', options: ['قلّلوا من استهلاك البلاستيك', 'أعادوا تدوير النفايات', 'زرعوا الأشجار', 'لوّثوا الأنهار'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'الوعي البيئي يؤدي لسلوكيات إيجابية تجاه البيئة، وتلويث الأنهار يناقضها.'),
  Question(id: 'q265', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"تفاوض الطرفان بعقلانية ومرونة وحسن نية وعناد."', options: ['عقلانية', 'مرونة', 'حسن نية', 'عناد'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'المرونة وحسن النية في التفاوض يتناقضان مع العناد.'),
  Question(id: 'q266', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"استعاد الاقتصاد عافيته بعد الأزمة فارتفعت الصادرات وانخفضت البطالة وتحسنت الأسواق وتراجع الإنتاج."', options: ['ارتفعت الصادرات', 'انخفضت البطالة', 'تحسنت الأسواق', 'تراجع الإنتاج'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'استعادة العافية الاقتصادية تعني مؤشرات إيجابية، وتراجع الإنتاج يناقضها.'),
  Question(id: 'q267', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"تعامل المعلم مع طلابه بصبر وتفهم وتشجيع وقسوة."', options: ['صبر', 'تفهم', 'تشجيع', 'قسوة'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'الصبر والتفهم والتشجيع صفات المعلم الجيد، والقسوة تناقضها.'),

  // ── الخطأ السياقي (صعب) ─────────────────────────────────
  Question(id: 'q268', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"عُرف ذلك المصلح بحكمته وبعد نظره وحرصه على مصلحة أمته وأنانيته المفرطة."', options: ['حكمته', 'بعد نظره', 'حرصه على مصلحة أمته', 'أنانيته المفرطة'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الحرص على مصلحة الأمة يناقض الأنانية، فالمصلح الحقيقي يقدّم مصلحة غيره على مصلحته.'),
  Question(id: 'q269', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"تميزت تلك الفترة التاريخية بالاستقرار السياسي وازدهار التجارة ورخاء الشعوب وتفشي المجاعات."', options: ['الاستقرار السياسي', 'ازدهار التجارة', 'رخاء الشعوب', 'تفشي المجاعات'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الرخاء والازدهار يتناقضان مع تفشي المجاعات.'),
  Question(id: 'q270', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"واجه المفكر انتقادات معاصريه بصدر رحب وحجج دامغة وثبات على مبادئه وانصياع تام لآرائهم."', options: ['صدر رحب', 'حجج دامغة', 'ثبات على مبادئه', 'انصياع تام لآرائهم'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الثبات على المبادئ يعني عدم التنازل عنها، وهذا يناقض الانصياع التام لآراء المعارضين.'),
  Question(id: 'q271', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"اتسمت سياسة ذلك الحاكم بالحكمة والعدل والرأفة برعيته والاستبداد بالسلطة."', options: ['الحكمة', 'العدل', 'الرأفة برعيته', 'الاستبداد بالسلطة'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'العدل والرأفة صفتان تناقضان الاستبداد بالسلطة.'),
  Question(id: 'q272', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"انتهج الباحث منهجاً علمياً دقيقاً قائماً على الموضوعية والحياد والتحقق من الأدلة والتحيز المسبق."', options: ['الموضوعية', 'الحياد', 'التحقق من الأدلة', 'التحيز المسبق'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'المنهج العلمي الدقيق يقوم على الموضوعية والحياد، وهذا يناقض التحيز المسبق.'),
  Question(id: 'q273', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"استطاع القائد أن يوحّد صفوف جيشه بالكاريزما والإقناع والقدوة الحسنة والتفرقة بينهم."', options: ['الكاريزما', 'الإقناع', 'القدوة الحسنة', 'التفرقة بينهم'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'توحيد الصفوف يناقض التفرقة بين الجنود.'),
  Question(id: 'q274', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"تجلّت عبقرية ذلك المهندس في دقة التصميم وابتكار الحلول وإتقان التنفيذ والاستهتار بالتفاصيل."', options: ['دقة التصميم', 'ابتكار الحلول', 'إتقان التنفيذ', 'الاستهتار بالتفاصيل'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الدقة والإتقان يناقضان الاستهتار بالتفاصيل.'),
  Question(id: 'q275', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"عالجت الحكومة الأزمة الاقتصادية بحزمة إصلاحات جريئة وشفافية في القرارات ومحاسبة للمقصرين وتستّر على الفساد."', options: ['حزمة إصلاحات جريئة', 'شفافية في القرارات', 'محاسبة للمقصرين', 'تستّر على الفساد'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الشفافية والمحاسبة تناقضان التستر على الفساد.'),
  Question(id: 'q276', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"تجلّى نضج ذلك السياسي في حنكته الدبلوماسية وقدرته على التوفيق بين المصالح المتضاربة وتهوّره في اتخاذ القرارات المصيرية."', options: ['حنكته الدبلوماسية', 'قدرته على التوفيق بين المصالح المتضاربة', 'نضجه', 'تهوّره في اتخاذ القرارات المصيرية'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الحنكة والنضج يناقضان التهور في القرارات المصيرية.'),

  // ── دفعة إضافية: إكمال جمل وخطأ سياقي (لضمان التوازن) ────
  Question(id: 'q277', text: 'أكمل الجملة بالكلمة المناسبة:\n"حرص الأب على ______ أبنائه منذ الصغر على قيم الصدق والأمانة."', options: ['تربية', 'إهمال', 'تجاهل', 'إبعاد'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'غرس القيم في الأبناء يكون عبر التربية.'),
  Question(id: 'q278', text: 'أكمل الجملة بالكلمة المناسبة:\n"بعد يوم طويل من العمل، شعر العامل بـ______ شديد فأوى إلى فراشه مبكراً."', options: ['تعب', 'نشاط', 'حماس', 'فرح'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'العودة المبكرة للنوم بعد يوم طويل من العمل تدل على التعب.'),
  Question(id: 'q279', text: 'أكمل الجملة بالكلمة المناسبة:\n"يحرص السائق الحذر على ______ قواعد المرور لتجنب الحوادث."', options: ['اتباع', 'مخالفة', 'تجاهل', 'كسر'], correctIndex: 0, difficulty: Difficulty.beginner, explanation: 'السائق الحذر الذي يريد تجنب الحوادث يتبع القواعد.'),
  Question(id: 'q280', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"استقبل الجيران المولود الجديد بالتهاني والورود والابتسامات والعبوس."', options: ['التهاني', 'الورود', 'الابتسامات', 'العبوس'], correctIndex: 3, difficulty: Difficulty.beginner, explanation: 'استقبال مولود جديد مناسبة سعيدة، والعبوس يناقض هذا الفرح.'),
  Question(id: 'q281', text: 'أكمل الجملة بالكلمة المناسبة:\n"يسعى المستثمرون إلى ______ أموالهم في مشاريع تحقق عائداً مضموناً."', options: ['استثمار', 'إهدار', 'إتلاف', 'إخفاء'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'الغاية من امتلاك المال وتحقيق العائد هي الاستثمار.'),
  Question(id: 'q282', text: 'أكمل الجملة بالكلمة المناسبة:\n"يميل الرأي العام إلى ______ السياسات التي تصب في مصلحة المواطن مباشرة."', options: ['تأييد', 'رفض', 'مقاطعة', 'استنكار'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'ما يصب في مصلحة المواطن غالباً يلقى التأييد لا الرفض.'),
  Question(id: 'q283', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"خطط الفريق للمشروع بعناية ووزّع المهام بوضوح وحدد الأهداف بدقة وأهمل المتابعة."', options: ['خطط بعناية', 'وزّع المهام بوضوح', 'حدد الأهداف بدقة', 'أهمل المتابعة'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'التخطيط الدقيق والتوزيع الواضح يتناقضان مع إهمال المتابعة.'),
  Question(id: 'q284', text: 'أكمل الجملة بالكلمة المناسبة:\n"يتّصف النقد البنّاء بأنه يهدف إلى ______ لا مجرد التجريح والانتقاص."', options: ['الإصلاح', 'الإحباط', 'التهكم', 'السخرية'], correctIndex: 0, difficulty: Difficulty.hard, explanation: '"لا مجرد التجريح" تدل على غاية إيجابية للنقد البنّاء، وهي الإصلاح.'),
  Question(id: 'q285', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"يتطلب الحوار الهادئ الإصغاء الجيد واحترام الرأي الآخر والابتعاد عن التعصب والإصرار على الرأي دون دليل."', options: ['الإصغاء الجيد', 'احترام الرأي الآخر', 'الابتعاد عن التعصب', 'الإصرار على الرأي دون دليل'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الحوار الهادئ يستلزم الانفتاح على الرأي الآخر، وهذا يناقض الإصرار على الرأي دون دليل.'),
  Question(id: 'q286', text: 'أكمل الجملة بالكلمة المناسبة:\n"يُعدّ الاعتراف بالخطأ من علامات ______ لا الضعف كما يظن البعض."', options: ['القوة', 'الهزيمة', 'العجز', 'الاستسلام'], correctIndex: 0, difficulty: Difficulty.hard, explanation: '"لا الضعف كما يظن البعض" تدل على أن المعنى الصحيح عكس الضعف، أي القوة.'),

  // ── دفعة موازنة أخيرة (متوسط وصعب) ──────────────────────
  Question(id: 'q287', text: 'أكمل الجملة بالكلمة المناسبة:\n"سعى التاجر إلى ______ ثقة عملائه من خلال الصدق في التعامل."', options: ['كسب', 'إضاعة', 'خسارة', 'تبديد'], correctIndex: 0, difficulty: Difficulty.intermediate, explanation: 'الصدق في التعامل وسيلة لكسب ثقة العملاء لا إضاعتها.'),
  Question(id: 'q288', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"استقبل الفريق الفائز بالتصفيق والهتاف والفرح والاستياء."', options: ['التصفيق', 'الهتاف', 'الفرح', 'الاستياء'], correctIndex: 3, difficulty: Difficulty.intermediate, explanation: 'استقبال الفريق الفائز مناسبة سعيدة، والاستياء يناقض هذا الفرح.'),
  Question(id: 'q289', text: 'أكمل الجملة بالكلمة المناسبة:\n"أدرك الطلاب أن ______ في المذاكرة اليومية أفضل من التكديس قبل الامتحان بيوم."', options: ['الانتظام', 'التقطع', 'الانقطاع', 'التوقف'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'مقابلة "التكديس قبل الامتحان" تستلزم معنى الاستمرار المنظم، وهو "الانتظام".'),
  Question(id: 'q290', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"تميزت إدارة الشركة بالرؤية الثاقبة والتخطيط الاستراتيجي والقرارات الحكيمة والارتجال العشوائي."', options: ['الرؤية الثاقبة', 'التخطيط الاستراتيجي', 'القرارات الحكيمة', 'الارتجال العشوائي'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'التخطيط الاستراتيجي والقرارات الحكيمة تناقض الارتجال العشوائي.'),
  Question(id: 'q291', text: 'أكمل الجملة بالكلمة المناسبة:\n"يُقاس تقدم الأمم بمدى ______ شعوبها بالعلم والمعرفة لا بكثرة ثرواتها فقط."', options: ['تسلّح', 'استهانة', 'جهل', 'تفريط'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'التقدم الحقيقي يرتبط بالتسلح بالعلم والمعرفة، وهو معنى إيجابي يوافق سياق المدح.'),
  Question(id: 'q292', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"جاءت خطة الإصلاح شاملة ومدروسة وواقعية ومرتجلة في آن واحد."', options: ['شاملة', 'مدروسة', 'واقعية', 'مرتجلة'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الخطة المدروسة والواقعية تناقض كونها مرتجلة.'),
  Question(id: 'q293', text: 'أكمل الجملة بالكلمة المناسبة:\n"يُحسن القائد الناجح ______ الاختلاف في الرأي بما يخدم مصلحة الفريق."', options: ['توظيف', 'إقصاء', 'تجاهل', 'قمع'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'القيادة الناجحة تستثمر الاختلاف في الرأي لخدمة الفريق بدل إقصائه.'),
  Question(id: 'q294', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"بُني ذلك الصرح العلمي على أسس راسخة من البحث الدؤوب والتجربة المتأنية والمراجعة الدقيقة والاستنتاج المتسرع."', options: ['البحث الدؤوب', 'التجربة المتأنية', 'المراجعة الدقيقة', 'الاستنتاج المتسرع'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'التأني والدقة العلمية يناقضان الاستنتاج المتسرع.'),
  Question(id: 'q295', text: 'أكمل الجملة بالكلمة المناسبة:\n"يتطلب بناء السلام الدائم بين الشعوب ______ الأحقاد التاريخية لا إذكاءها."', options: ['تجاوز', 'إحياء', 'استحضار', 'تأجيج'], correctIndex: 0, difficulty: Difficulty.hard, explanation: '"لا إذكاءها" تدل على أن المعنى المطلوب عكس التأجيج، وهو التجاوز.'),
  Question(id: 'q296', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"عالج الروائي في عمله قضايا إنسانية عميقة بحس مرهف وأسلوب أخّاذ ولغة راقية وحبكة مفككة."', options: ['حس مرهف', 'أسلوب أخّاذ', 'لغة راقية', 'حبكة مفككة'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'وصف العمل الأدبي بالإتقان (حس مرهف، أسلوب أخاذ، لغة راقية) يناقض وصف حبكته بالتفكك.'),
  Question(id: 'q297', text: 'أكمل الجملة بالكلمة المناسبة:\n"من الحكمة أن ______ الإنسان من أخطاء الماضي بدل تكرارها."', options: ['يتّعظ', 'يتجاهل', 'ينسى', 'يعيد'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'الاستفادة من الأخطاء بدل تكرارها هو معنى "يتّعظ".'),
  Question(id: 'q298', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"اتّسمت مسيرة ذلك العالِم بالتجرد للعلم والتفاني في البحث والزهد في الأضواء والسعي الحثيث وراء الشهرة."', options: ['التجرد للعلم', 'التفاني في البحث', 'الزهد في الأضواء', 'السعي الحثيث وراء الشهرة'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الزهد في الأضواء يناقض السعي الحثيث وراء الشهرة.'),
  Question(id: 'q299', text: 'أكمل الجملة بالكلمة المناسبة:\n"يُعدّ التفكير النقدي مهارة ______ تمكّن الفرد من تمحيص الأفكار قبل قبولها."', options: ['أساسية', 'زائدة', 'عابرة', 'مهملة'], correctIndex: 0, difficulty: Difficulty.hard, explanation: 'وصف "تمكّن الفرد من تمحيص الأفكار" يدل على أهمية هذه المهارة، وهذا معنى "أساسية".'),
  Question(id: 'q300', text: 'حدد الكلمة التي لا تتفق مع سياق الجملة:\n"انتهج المفاوض أسلوباً هادئاً قائماً على الإنصات والتفهم والصبر والاستفزاز المتعمد."', options: ['الإنصات', 'التفهم', 'الصبر', 'الاستفزاز المتعمد'], correctIndex: 3, difficulty: Difficulty.hard, explanation: 'الأسلوب الهادئ القائم على الإنصات والصبر يناقض الاستفزاز المتعمد.'),
];
